#!/usr/bin/env python3
"""Build the hand-curated public evidence catalog; does not run a model or invent labels."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[2]
AS_OF = '2026-09-10'
RETRIEVED = '2026-09-10T17:35:10Z'
SOURCES=[]
CANDIDATES=[]

def source(id, title, url, publisher, date, summary, kind='sponsor', excerpt=None):
    row=dict(id=id,title=title,url=url,publisher=publisher,publishedAt=date,retrievedAt=RETRIEVED,kind=kind,summary=summary)
    if excerpt: row['excerpt']=excerpt
    SOURCES.append(row)
    return id

def milestone(id,date,title,detail,kind,*refs):
    return dict(id=id,date=date,title=title,detail=detail,kind=kind,sourceIds=list(refs))

def signal(id,label,detail,direction,category,*refs):
    return dict(id=id,label=label,detail=detail,direction=direction,category=category,sourceIds=list(refs))

def candidate(id,drug,indication,sponsor,ticker,modality,phase,reviewType,applicationType,nctIds,targetDate,summary,milestones,signals,*refs):
    source_ids=list(dict.fromkeys([*refs,*[r for e in milestones+signals for r in e['sourceIds']]]))
    CANDIDATES.append(dict(id=id,drug=drug,indication=indication,sponsor=sponsor,ticker=ticker,modality=modality,phase=phase,reviewType=reviewType,applicationType=applicationType,nctIds=nctIds,status='under_review',targetDate=targetDate,targetDateKind='reported' if targetDate else 'unknown',asOf=AS_OF,summary=summary,sourceIds=source_ids,milestones=milestones,signals=signals))

